mapper.select:
SELECT COUNT(*) FROM train_server s WHERE s.enabled = 1 AND EXISTS (
 SELECT 1 FROM train_server_account a WHERE a.server_id = s.server_id AND a.enabled = 1
 AND a.status IN ('ONLINE','DEGRADED') AND a.last_probe_at = a.last_success_at
 AND a.last_success_at >= #{freshAfter} AND a.last_success_at <= #{now}
 AND a.owner_user_id = #{ownerUserId}
)

mapper.update:
      UPDATE train_server SET name=#{name}, host_key_sha256=#{fingerprint},
          enabled=COALESCE(#{enabled}, enabled), updated_at=#{updatedAt}
WHERE server_id=#{serverId}
